INSERT INTO creature_text (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
  (23837, 0, 0, 'Scrying upon many insignificant situations within Icecrown, you stumble upon something interesting...', 42, 0, 100, 0, 0, 0, 0, 0, 'Eye of Lich King Ambient'),
  (34668, 0, 0, 'Haha! that should be a blast!', 12, 0, 100, 25, 0, 0, 0, 0, 'say Text'),
  (34668, 1, 0, 'He''ll get me more later? How are we supposed to get you promoted to Trade Prince without our number one product on the shelves?', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34668, 2, 0, 'Ace, Izzy, Gobber, you three make sure you tag a long with $N and help him take care of those dead beats!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34668, 3, 0, 'Go get ''em, boss!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34668, 4, 0, 'You better get upstairs pronto, boss. Trade Prince Gallywix is waiting for you.', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34668, 5, 0, '$N, you have to hurry and break your moolah out of the bank!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34668, 6, 0, 'I can''t stand to watch. So many good memories. So much profit.', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34668, 7, 0, 'The Trade Prince''s yacht is about to set sail. Everyone,get to the dock! Hand over the keys, boss. I''m driving. Just let me know when you''re ready to go.', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34673, 0, 0, 'All you have to do is let me show you how to make a safe shot, then make one yourself on a training dummy.', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (34689, 0, 0, 'All you have to do is let me show you how to launch Arcane Missiles. Then, head to one of the training dummies Bamm is shooting at, fire a fireball at him, and destroy him with the missiles.', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (34692, 0, 0, 'Nothing wrong with a little drive-by fortitude!', 12, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (34692, 0, 1, 'I really should charge you for that.', 12, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (34692, 0, 2, 'I was wondering when I''d see you again, $n.', 12, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (34692, 0, 3, 'It''s not much, but it just might keep your green skin intact.', 12, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (34692, 0, 4, 'Light be with you... for the very low price of a one silver tithe!', 12, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (34692, 1, 0, 'All you have to do is let me show you how to cast Quick Heal, and then use the spell on some of the injured employees lying around. I''m sure they will not even tip, stingy!', 12, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (34693, 0, 0, 'I will adjust the cap to activate automatically when you are at the villa. Just be careful to avoid pigs!', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (34693, 1, 0, 'All you have to do is let me show you how to eviscerate. Then head for one of the training dummies Bamm is shooting at, launch a pernicious attack, and finish with evisceration.', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (34695, 0, 0, 'Would one of you hurry up and finish off the other? Some of us are trying to make some moolah here!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34695, 1, 0, 'How did the two of you ever make it to the executive level?', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (34696, 0, 0, 'All you have to do is let me show you how to launch Immolation, then use the spell on one of the training dummies that Bamm is shooting at. Light the fire!', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (34697, 0, 0, 'Insert your coins so that the NX-01 Mechanic Warrior teaches you how to charge. Then use the technique on one of the training dummies.', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (34830, 0, 0, 'Don''t tase me, mon!', 12, 0, 100, 5, 0, 0, 0, 0, 'Defiant Troll'),
  (34830, 0, 1, 'I report you to HR!', 12, 0, 100, 5, 0, 0, 0, 0, 'Defiant Troll'),
  (34830, 0, 2, 'I''m going. I''m going!', 12, 0, 100, 15, 0, 0, 0, 0, 'Defiant Troll'),
  (34830, 0, 3, 'Oops, break''s over.', 12, 0, 100, 1, 0, 0, 0, 0, 'Defiant Troll'),
  (34830, 0, 4, 'Sorry, mon. It won''t happen again.', 12, 0, 100, 5, 0, 0, 0, 0, 'Defiant Troll'),
  (34830, 0, 5, 'What I doin'' wrong? Don''t I get a lunch and two breaks a day, mon?', 12, 0, 100, 5, 0, 0, 0, 0, 'Defiant Troll'),
  (34830, 0, 6, 'Work was bettah in da Undermine!', 12, 0, 100, 5, 0, 0, 0, 0, 'Defiant Troll'),
  (34835, 0, 0, 'I was just comin'' to see you, Honest!', 12, 0, 100, 0, 0, 0, 0, 0, 'say Text on Aggro'),
  (34835, 1, 0, 'Dam, you got me!', 12, 0, 100, 16, 0, 0, 0, 0, 'say Text on Beat'),
  (34872, 0, 0, 'It is always pleasant to receive a gift from the hand of the second in person. I''m going to the baller immediately!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34872, 1, 0, 'OUCH!', 14, 0, 100, 34, 0, 0, 0, 0, 'say Text'),
  (34872, 2, 0, 'Okay, okay! I understand the message!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34872, 3, 0, 'Chief, tell Chipie I''ll kick him if  Kaja''Cola  will get more later then that production has resumed.', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34872, 4, 0, 'I can''t to believe the nerve of those trolls. Rebelling after all that I''ve done for them!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34872, 5, 0, 'Useless! You are simply useless! I fear that we are all obligate to throw you into the Maelstrom!', 14, 0, 50, 22, 0, 0, 0, 0, 'say Text'),
  (34872, 5, 1, 'You want us go bash bad trolls?', 12, 0, 50, 0, 0, 0, 0, 0, 'say Text'),
  (34874, 0, 0, 'Ooh, I think you''re gonna like this, boss!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34874, 1, 0, 'Use the Keys to the Hod Rod to get into your car. Pick up your friends, Izzy, Ace and Gobber.', 41, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34874, 2, 0, 'Here they are! Okay, you three make sure that you help him out today. He''s got a lot of stuff to take care of before the party!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34874, 3, 0, 'Use your Hot Rod to run over Hired looters and get their loot.', 41, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34876, 0, 0, 'Oh no, you didn''t!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (34876, 1, 0, 'What? Fine,fine... I''ll pay my protection moolah to your goons!', 12, 0, 100, 16, 0, 0, 0, 0, 'say Text'),
  (34877, 0, 0, '<Jack reported something about the hammer, which would be its armead you think.>', 12, 0, 100, 0, 0, 0, 0, 0, 'say Text on Aggro'),
  (34877, 1, 0, 'Jack the Hammer grunts and give up, clearly beaten.', 16, 0, 100, 16, 0, 0, 0, 0, 'say Text on Beat'),
  (34878, 0, 0, 'I''m tryin'' to run a business here!', 12, 0, 100, 0, 0, 0, 0, 0, 'say Text on Aggro'),
  (34878, 1, 0, 'Not the face, not the face!', 12, 0, 100, 16, 0, 0, 0, 0, 'say Text on Beat'),
  (35053, 0, 0, 'Make sure you pull plenty of moolah out of the bank. I don''t want you buying any of that cheap clothing you usually like to wear. This party''s important!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (35053, 1, 0, 'You''re the most handsome boyfriend a girl could hope for. Knock''em dead, honey!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (35053, 2, 0, 'You''re dressed to impress! Use your new powers below to make your party guests happy!', 41, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (35053, 3, 0, 'We''re through, $N! I''m with Chip now.', 12, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (35054, 0, 0, 'Think to take a large flouze package at the Bank. I do not want you too look at these poor clothes you like to wear usual. This day is important!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (35054, 1, 0, 'You''re dressed to impress! Use your new powers below to make your party guests happy!', 41, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (35054, 2, 0, 'We''re through, $N! I''m with Candy now.', 12, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
