  (36519, 0, 6, 'By the looks of that thing I might take my chances swimming with the sharks!', 12, 0, 100, 5, 0, 0, 0, 0, ''),
  (36600, 0, 0, 'Yeah, there are lots of people coincs in escape pods, boss. Uh, wait. In fact, the more you your boss. In any case, they will probably all drown if we do not help.', 12, 0, 100, 1, 0, 0, 0, 0, 'Geargrinder Gizmo'),
