  (38120, 3, 0, '$n, over here if you please.', 12, 0, 100, 3, 0, 0, 0, 0, ''),
  (38120, 4, 0, 'Don''t underestimate the Mechachicken, $n. After all, it is a Hobart Grapplehammer invention!', 12, 0, 100, 274, 0, 0, 0, 0, ''),
  (38120, 5, 0, 'The marketing research Megs has conducted suggests that a naga invasion is imminent!', 12, 0, 100, 5, 0, 0, 0, 0, ''),
  (38120, 6, 0, 'Take your time, my $g boy : girl;. Now what can I modify this shredder boot to be? Hmm.', 12, 0, 100, 6, 0, 0, 0, 0, ''),
  (38120, 7, 0, 'I''ve set the Bootzooka to fire several rockets per shot. I''m fairly certain that I perfectly calibrated the targeting.', 12, 0, 100, 273, 0, 0, 0, 0, ''),
  (38120, 8, 0, 'Booster rockets for cages. What will I think of next? I am a genius!', 12, 0, 100, 11, 0, 0, 0, 0, ''),
