  (48496, 2, 0, 'Greely sighs and rolls her eyes.', 16, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (48496, 3, 0, 'Yes, Doctor Grapplehammer.', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (48496, 4, 0, 'The assistant shakes her head.', 16, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (48496, 5, 0, 'Greely coughs.', 16, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (48496, 6, 0, 'Um, Hobart, you''re at the controls.', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (48496, 7, 0, 'Ya think? Hobart, the Micro Mechachicken is destabilizing. It''s expanding!', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (48496, 8, 0, 'It''s the one on the far right! Hurry, Hobart! It''s going to eggsplode!', 14, 0, 100, 5, 0, 0, 0, 0, 'say Text'),
  (48496, 9, 0, 'WHAT?!!!', 14, 0, 100, 5, 0, 0, 0, 0, 'say Text'),
  (48496, 10, 0, 'We''re still alive, Doctor Grapplehammer, despite your best efforts.', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (48496, 11, 0, 'Is that egg on your face?', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (48496, 12, 0, 'Hobart''s jaw hits the ground.', 16, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (48496, 13, 0, 'Now what''s this about you ''always loved me'', Grapplehammer?', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (48496, 14, 0, 'We can both agree on that, doctor.', 12, 0, 100, 1, 0, 0, 0, 0, 'say Text'),
  (366150, 0, 0, 'On my way!', 14, 0, 100, 0, 0, 0, 0, 0, '38775'),
  (366150, 0, 1, 'Just a sec!', 12, 0, 100, 0, 0, 0, 0, 0, '38776'),
  (366150, 0, 2, 'I only have two hands and two feet here!', 14, 0, 100, 0, 0, 0, 0, 0, '38777'),
  (366150, 0, 3, 'I hope I don''t run out of bandages!', 12, 0, 100, 0, 0, 0, 0, 0, '38778'),
  (366150, 0, 4, 'I need an assistant!', 12, 0, 100, 0, 0, 0, 0, 0, '38779'),
  (366150, 0, 5, 'Someone needs to do something about that giant turtle in the cave!', 14, 0, 100, 0, 0, 0, 0, 0, '38780');
